U='u04'
def run(n,sid,printed,title,tu,tp,P,note):
    s=page(n,U,printed,title,tu,tp,sid)
    F=Flow(s)
    for k,a,b,d,*m in P: add(s,k,a,b,d,**(m[0] if m else {}))
    F.done()
    s['sourceNote']=note
    s['vocabulary']={}
    save(s)
